.n15{counter-reset:n15 var(--n15);animation:n15-c 1.8s cubic-bezier(.16,1,.3,1) 0.55s both}
.n15::after{content:counter(n15,decimal)}
@keyframes n15-c{from{--n15:0}to{--n15:208}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
